16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+?[0-9]{8,15}$",
49	            message = "Phone number must be an E.164 number ('+' and 8-15 digits) or 8-15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "household_id")
62	    private String householdId;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    /**
68	     * Derived, non-persisted flag set during the create flow: true when more than 80
69	     * owners had already been created for this owner's business day at the time of
70	     * registration. Returned as {@code bulkSignupWarning}; null (treated as false) for
71	     * owners loaded from the database, which never carry the create-time snapshot.
72	     */
73	    @Transient
74	    private Boolean bulkSignupWarning;
75	
76	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
77	    private Set<Pet> pets;
78	
79	    public String getAddress() {
80	        return this.address;
81	    }
82	
83	    public void setAddress(String address) {
84	        this.address = address;
85	    }
86	
87	    public String getCity() {
88	        return this.city;
89	    }
90	
91	    public void setCity(String city) {
92	        this.city = city;
93	    }
94	
95	    public String getTelephone() {
96	        return this.telephone;
97	    }
98	
99	    public void setTelephone(String telephone) {
100	        this.telephone = telephone;
101	    }
102	
103	    public String getEmail() {
104	        return this.email;
105	    }
106	
107	    public void setEmail(String email) {
108	        this.email = email;
109	    }
110	
111	    public LocalDate getRegistrationDate() {
112	        return this.registrationDate;
113	    }
114	
115	    public void setRegistrationDate(LocalDate registrationDate) {
116	        this.registrationDate = registrationDate;
117	    }
118	
119	    public String getCustomerCode() {
120	        return this.customerCode;
121	    }
122	
123	    public void setCustomerCode(String customerCode) {
124	        this.customerCode = customerCode;
125	    }
126	
127	    public String getHouseholdId() {
128	        return this.householdId;
129	    }
130	
131	    public void setHouseholdId(String householdId) {
132	        this.householdId = householdId;
133	    }
134	
135	    public Integer getNamesakeCount() {
136	        return this.namesakeCount;
137	    }
138	
139	    public void setNamesakeCount(Integer namesakeCount) {
140	        this.namesakeCount = namesakeCount;
141	    }
142	
143	    public Boolean getBulkSignupWarning() {
144	        return this.bulkSignupWarning;
145	    }
146	
147	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
148	        this.bulkSignupWarning = bulkSignupWarning;
149	    }
150	
151	    protected Set<Pet> getPetsInternal() {
152	        if (this.pets == null) {
153	            this.pets = new HashSet<>();
154	        }
155	        return this.pets;
156	    }
157	
158	    protected void setPetsInternal(Set<Pet> pets) {
159	        this.pets = pets;
160	    }
161	
162	    public List<Pet> getPets() {
163	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
164	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
165	        return Collections.unmodifiableList(sortedPets);
166	    }
167	
168	    public void setPets(List<Pet> pets) {
169	        this.pets = new HashSet<>(pets);
170	    }
171	
172	    public void addPet(Pet pet) {
173	        getPetsInternal().add(pet);
174	        pet.setOwner(this);
175	    }
176	
177	    /**
178	     * Return the Pet with the given name, or null if none found for this Owner.
179	     *
180	     * @param name to test
181	     * @return true if pet name is already in use
182	     */
183	    public Pet getPet(String name) {
184	        return getPet(name, false);
185	    }
186	
187	    /**
188	     * Return the Pet with the given name, or null if none found for this Owner.
189	     *
190	     * @param name to test
191	     * @return true if pet name is already in use
192	     */
193	    public Pet getPet(String name, boolean ignoreNew) {
194	        name = name.toLowerCase();
195	        for (Pet pet : getPetsInternal()) {
196	            if (!ignoreNew || !pet.isNew()) {
197	                String compName = pet.getName();
198	                compName = compName.toLowerCase();
199	                if (compName.equals(name)) {
200	                    return pet;
201	                }
202	            }
203	        }
204	        return null;
205	    }
206	
207	    public Pet getPet(Integer petId) {
208	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
209	    }
210	
211	    @Override
212	    public String toString() {
213	        return new ToStringCreator(this)
214	
215	            .append("id", this.getId())
216	            .append("new", this.isNew())
217	            .append("lastName", this.getLastName())
218	            .append("firstName", this.getFirstName())
219	            .append("address", this.address)
220	            .append("city", this.city)
221	            .append("telephone", this.telephone)
222	            .toString();
223	    }
224	}
