1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    @Mapping(target = "bulkSignupWarning",
28	            expression = "java(owner.getBulkSignupWarning() != null && owner.getBulkSignupWarning())")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /** Upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
32	    default String initials(Owner owner) {
33	        return owner.getFirstName().substring(0, 1).toUpperCase()
34	                + "." + owner.getLastName().substring(0, 1).toUpperCase() + ".";
35	    }
36	
37	    /** Membership number '<customerCode>-M<YY>', YY = last two digits of the
38	     *  registrationDate year. Null unless both source fields are present. */
39	    default String membershipNumber(Owner owner) {
40	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
41	            return null;
42	        }
43	        return String.format("%s-M%02d", owner.getCustomerCode(),
44	                owner.getRegistrationDate().getYear() % 100);
45	    }
46	
47	    /** Membership tier: 'SILVER' when namesakeCount is 0 and an email is present,
48	     *  otherwise 'BRONZE'. */
49	    default String membershipTier(Owner owner) {
50	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
