1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
14	
15	/**
16	 * When the create request opted in with {@code sharesHousehold} true, joins the new
17	 * owner to the household of any existing owner with the same {@code lastName} and
18	 * {@code address} (addresses compared in their normalized form via
19	 * {@link AddressNormalizer}, last names case-insensitively after collapsing whitespace —
20	 * the same rule {@link RejectDuplicateOwnerHousehold} uses to detect duplicates).
21	 *
22	 * <p>A household is identified by a stable {@code householdId} derived from the
23	 * normalized lastName and address, so every member of the same household resolves to
24	 * the same value regardless of registration order. Both the new owner and each matched
25	 * existing owner are assigned that id (existing members are persisted here; the new
26	 * owner is persisted by the later {@link SaveOwner} step). Runs inside the create
27	 * transaction, so this and the new owner's save commit together.
28	 *
29	 * <p>No-ops when {@code sharesHousehold} is not true or when no matching owner exists.
30	 */
31	public class AssignOwnerHousehold {
32	
33	    public void service(@Val Owner owner, @Val OwnerFieldsDto request,
34	            OwnerRepository ownerRepository) {
35	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
36	            return; // did not opt into sharing a household
37	        }
38	        String lastName = normalize(owner.getLastName());
39	        String address = AddressNormalizer.normalize(owner.getAddress());
40	        if (lastName == null || address == null) {
41	            return; // nothing to match on
42	        }
43	        List<Owner> matches = new ArrayList<>();
44	        for (Owner existing : ownerRepository.findAll()) {
45	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
46	                continue; // never match the owner against itself
47	            }
48	            if (lastName.equals(normalize(existing.getLastName()))
49	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
50	                matches.add(existing);
51	            }
52	        }
53	        if (matches.isEmpty()) {
54	            return; // no household to join
55	        }
56	        // Reuse an existing member's id if present, otherwise derive a stable one.
57	        String householdId = deriveHouseholdId(lastName, address);
58	        for (Owner match : matches) {
59	            if (match.getHouseholdId() != null) {
60	                householdId = match.getHouseholdId();
61	                break;
62	            }
63	        }
64	        owner.setHouseholdId(householdId);
65	        for (Owner match : matches) {
66	            if (!householdId.equals(match.getHouseholdId())) {
67	                match.setHouseholdId(householdId);
68	                ownerRepository.save(match);
69	            }
70	        }
71	    }
72	
73	    /** Stable {@code 'HH-<16 hex>'} identifier for the household keyed by lastName+address. */
74	    private static String deriveHouseholdId(String lastName, String address) {
75	        try {
76	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
77	            byte[] hash = digest.digest((lastName + "�" + address).getBytes(StandardCharsets.UTF_8));
78	            StringBuilder sb = new StringBuilder("HH-");
79	            for (int i = 0; i < 8; i++) {
80	                sb.append(String.format("%02X", hash[i]));
81	            }
82	            return sb.toString();
83	        }
84	        catch (NoSuchAlgorithmException e) {
85	            throw new IllegalStateException("SHA-256 not available", e);
86	        }
87	    }
88	
89	    /** Last-name key: lower-cased, trimmed, with internal whitespace runs collapsed to one space. */
90	    private static String normalize(String value) {
91	        if (value == null) {
92	            return null;
93	        }
94	        String collapsed = value.trim().replaceAll("\\s+", " ");
95	        return collapsed.isEmpty() ? null : collapsed.toLowerCase(Locale.ROOT);
96	    }
97	}
