1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many owners already exist that share the new owner's first and last
9	 * name, compared case-insensitively. Runs before {@link SaveOwner} so the owner
10	 * being created is not yet persisted and therefore never counts itself. Mutates the
11	 * {@link Owner} in place so the value is persisted and returned as
12	 * {@code namesakeCount}.
13	 */
14	public class AssignOwnerNamesakeCount {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String firstName = owner.getFirstName();
18	        String lastName = owner.getLastName();
19	        int count = 0;
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
22	                continue; // never count the owner itself
23	            }
24	            if (equalsIgnoreCase(firstName, existing.getFirstName())
25	                    && equalsIgnoreCase(lastName, existing.getLastName())) {
26	                count++;
27	            }
28	        }
29	        owner.setNamesakeCount(count);
30	    }
31	
32	    private static boolean equalsIgnoreCase(String a, String b) {
33	        return a == null ? b == null : a.equalsIgnoreCase(b);
34	    }
35	}
