9	/**
10	 * Assigns a newly created owner a {@code customerCode} formatted
11	 * {@code '<CITY3>-<LAST3>-<NNNN>'}: CITY3 is the upper-cased first three letters
12	 * of the owner's city, LAST3 the upper-cased first three letters of the owner's
13	 * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more
14	 * than the number of owners already in that city. Runs before {@link SaveOwner}
15	 * so the owner being created is not yet counted. Mutates the {@link Owner} in
16	 * place so it is persisted and returned with the code.
17	 */
18	public class AssignOwnerCustomerCode {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String city3 = first3Upper(owner.getCity());
22	        String last3 = first3Upper(owner.getLastName());
23	        String city = owner.getCity();
24	        long inCity = ownerRepository.findAll().stream()
25	                .filter(existing -> city == null ? existing.getCity() == null
26	                        : city.equals(existing.getCity()))
27	                .count();
28	        int sequence = (int) inCity + 1;
29	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
30	    }
31	
32	    private static String first3Upper(String value) {
33	        int len = Math.min(3, value.length());
34	        return value.substring(0, len).toUpperCase(Locale.ROOT);
35	    }
36	}
