11	 * created for the same business day (owners sharing this owner's adjusted
12	 * {@code registrationDate}), excluding the owner being created, and sets
13	 * {@code bulkSignupWarning} to true once that count exceeds {@value #WARNING_THRESHOLD}.
14	 *
15	 * <p>Runs after {@link DefaultOwnerRegistrationDate} (so the business-day registration
16	 * date is set) and before {@link SaveOwner} (so the owner being created is not yet
17	 * persisted and never counts itself). This is the same daily accumulation the
18	 * {@link RejectOwnerDailyLimit} rule counts, evaluated at a lower, non-rejecting
19	 * threshold. The value is a create-time snapshot returned as {@code bulkSignupWarning}.
20	 */
21	public class AssignOwnerBulkSignupWarning {
22	
23	    /** Owners already created today must exceed this for the warning to be raised. */
24	    static final int WARNING_THRESHOLD = 80;
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        LocalDate businessDay = owner.getRegistrationDate();
28	        long count = 0;
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
31	                continue; // never count the owner itself
32	            }
33	            if (businessDay.equals(existing.getRegistrationDate())) {
34	                count++;
35	            }
36	        }
37	        owner.setBulkSignupWarning(count > WARNING_THRESHOLD);
38	    }
39	}
