9	/**
10	 * Ensures a newly created owner's registration date falls on a business day.
11	 *
12	 * <p>The effective registration date is the one supplied in the request body, or the
13	 * server's current date when none was supplied. When that effective date is a Saturday
14	 * or Sunday it is rolled forward to the following Monday and stored as the
15	 * {@code registrationDate}. Because later steps read this same entity, every value
16	 * derived from the registration date (the membership number's year segment, the
17	 * daily create-limit) sees the adjusted business day.
18	 */
19	public class DefaultOwnerRegistrationDate {
20	
21	    public void service(@Val Owner owner) {
22	        LocalDate effective = owner.getRegistrationDate() != null
23	                ? owner.getRegistrationDate() : LocalDate.now();
24	        owner.setRegistrationDate(toBusinessDay(effective));
25	    }
26	
27	    /** Rolls a weekend date forward to the next Monday; business days are unchanged. */
28	    private static LocalDate toBusinessDay(LocalDate date) {
29	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
30	                || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
31	            date = date.plusDays(1);
32	        }
33	        return date;
34	    }
35	}
