20	            OwnerRepository ownerRepository) throws DuplicateOwnerHouseholdException {
21	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return; // explicitly allowed to share a household
23	        }
24	        String lastName = normalize(owner.getLastName());
25	        String address = AddressNormalizer.normalize(owner.getAddress());
26	        if (lastName == null || address == null) {
27	            return; // nothing to compare against
28	        }
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
31	                continue; // never conflict with the owner itself
32	            }
33	            if (lastName.equals(normalize(existing.getLastName()))
34	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
35	                throw new DuplicateOwnerHouseholdException(
36	                        "Another owner with the same last name and address already exists");
37	            }
38	        }
